window.T={en:{indexTitle:"Trimly | From long videos to highlights",privacyTitle:"Trimly | Privacy Policy",nav:{features:"Features",download:"Download",},hero:{heading:"Long videos.\nHighlights, within reach.",subtitle:"Open the original from Photos, an external drive, or your NAS. Mark as many clips, stills, or Live Photos as you like, then save them to Photos with the moment's real time, place, and quality intact.",cta:"Download on the App Store",purchaseNote:"One purchase for iPhone, iPad, Mac, and Apple TV. No subscription.",},useCasesHeading:"For the moments hiding inside long recordings.",useCases:[{title:"Travel days",body:"Arrival, street scenes, sunset, dinner. Split the day into clips, with time, place, and camera details intact.",},{title:"Live shows",body:"Record the full set. Save the best chorus clips and stage moments on their own.",},{title:"Parties",body:"Candles, gifts, eyes closed for a wish. Trim the moment, share it with the group, and let everyone keep it.",},{title:"Outdoor adventures",body:"Skiing, surfing, hiking, cycling. Mark the turn or sprint you are proud of and show everyone your best moment.",},{title:"Family moments",body:"Keep a first step, a pet's reaction, or a small moment you want to revisit without searching through the whole recording.",},],proofSections:[{title:"Open the original. Keep every highlight.",body:"Open long recordings directly from Photos, an external drive, or your NAS. Mark as many clips, stills, or Live Photos as you like, then export only what you want.",points:["Local, external, and SMB/WebDAV files","One recording, multiple clips, one batch export","No source copy or full-size duplicate",],shot:"source-file-clips",},{title:"Metadata handled correctly.",body:"Each clip or Live Photo can line up with the real time and place of the moment, so your library no longer turns messy.",points:["Calculates the real time of each clip","Keeps GPS and camera metadata","Gives your library a timeline that stays in order",],shot:"photos-metadata-export",},{title:"Mark on the go. Export at your desk.",body:"Your edit notes sync through iCloud. Mark clips on iPhone, then pick up on Mac when you are ready. Your own devices can continue working with the same source file on your NAS.",points:["Syncs edit notes, not video files","Same source file, edits stay linked after moves","Native tvOS app, or AirPlay when everyone wants to watch",],shot:"cross-device-editing",},{title:"Find clips intelligently.",body:"Use Apple's on-device features to search long videos before you start exporting. Results stay on your device, and you decide which moments become clips.",points:["Transcribe speech, translate it on supported OS versions, and export subtitles","Recognizes sound patterns to locate every laugh","Identifies a subject from one frame and finds every time they appear in the video",],shot:"local-intelligence",},{title:"Made for each screen.",body:"Trimly is not one interface stretched across devices. iPhone, iPad, and Mac each get their own rhythm.",points:["iPhone: carefully tuned for small screens","iPad: touch, keyboards, resizable windows","Mac: large-screen work with real file access","Native tvOS app, or AirPlay for watching together",],shot:"device-workspaces",shotAlt:"Trimly editing interface across different devices",},{title:"HDR & Log.",body:"The export pipeline is ready for HDR footage, common Log workflows, and lossless audio, so short clips can keep the qualities that matter.",points:["HDR-ready media pipeline",{text:"Built-in LOG recovery LUTs for popular devices",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"LUT disclaimer",},},"Lossless audio support, including raw PCM",],shot:"pro-media-pipeline",shotAlt:"Trimly audio waveform and export controls",},],privacy:{heading:"Local and Private",body:"No Trimly account, tracking, or telemetry. iCloud sync is used only for your edits and LUTs.",},footer:{home:"Home",support:"Support",privacy:"Privacy Policy",disclaimer:"Apple, Apple Log, iPhone, iPad, and Mac are trademarks of Apple Inc. GoPro is a trademark of GoPro, Inc. DJI is a trademark of SZ DJI Technology Co., Ltd. Insta360 is a trademark of Arashi Vision Inc. Trimly is developed independently and is not affiliated with, sponsored by, or endorsed by any of these companies. Bundled LUT files are provided to help users process their own footage for personal, non-commercial use only. All trademarks are the property of their respective owners.",},legal:{eyebrow:"Legal",title:"Privacy Policy",updated:"Last updated: July 10, 2026",intro:"Trimly processes your media entirely on your device. Your footage stays on your iPhone, iPad, or Mac. Your edits and LUTs can sync across your Apple devices via iCloud; video files are never uploaded. This policy explains, in plain terms, what that means for your privacy.",contactLabel:"Questions about privacy? Reach us at",sections:[{h:"No data collection",p:"Trimly does not collect, store, or transmit any personal information. There is no analytics, no tracking, no advertising identifiers, and no telemetry of any kind.",},{h:"iCloud sync",p:"Trimly does not connect to Trimly servers or any third-party services. The only network activity is iCloud sync, which uses Apple's iCloud to keep your edits and LUTs in sync across your devices when you enable it, subject to Apple's iCloud terms and privacy policy. Your video and audio files are never uploaded or synced.",},{h:"Files and Photos access",p:"When you open media from the Files app, USB storage, or your Photos Library, Trimly reads it only so you can trim and export it. All processing happens locally on your device, and exported clips are saved to the location you choose. Trimly accesses your Photos Library only with your permission, and only to import or save the media you select.",},{h:"No account, no third-party network access",p:"Trimly has no account system and no sign-in. Outside of Apple's built-in iCloud sync, it does not use any analytics services or cloud processing.",},{h:"AI features",p:"All AI features in Trimly are implemented using frameworks built into Apple systems. Trimly does not include, and will never download, any third-party AI models. It also does not provide user data to any third-party AI service providers. All processing happens locally on your device and fully follows the privacy policies that apply to AI features in Apple's systems.",},{h:"Children's privacy",p:"Because Trimly collects no data at all, it does not knowingly collect information from anyone, including children.",},{h:"Changes to this policy",p:"If this policy changes, the updated version will be posted on this page with a new date.",},],},},zh:{indexTitle:"Trimly | 长视频里的高光，回到相册",privacyTitle:"Trimly | 隐私政策",nav:{features:"功能",download:"下载",},hero:{heading:"长视频留在硬盘，\n高光回到相册",subtitle:"直接打开相册、外置硬盘或 NAS 里的原片。标出任意多个视频片段、截图或 Live Photo，再按真实的时间、地点和画质导入系统相册。",cta:"在 App Store 下载",purchaseNote:"一次购买，iPhone、iPad、Mac、Apple TV 全平台通用，无需订阅",},useCasesHeading:"记录很长，记忆却很短",useCases:[{title:"旅行随拍",body:"抵达、街景、日落、晚餐，各成一段；时间、地点、拍摄设备，全部保留",},{title:"现场演出",body:"先录完整场，再把最精彩的副歌片段与舞台高光单独保存",},{title:"聚会开趴",body:"吹蜡烛、拆礼物、闭眼许愿，随手裁出片段发到群里，让大家轻松珍藏",},{title:"户外探险",body:"滑雪、冲浪、登山、骑行，标出最得意的转弯与冲刺，让所有人看到你最炫的瞬间",},{title:"家人和宠物",body:"宝宝迈出的第一步、宠物突然的反应，或任何值得反复回看的小瞬间，都不用再从整段录像里慢慢找",},],proofSections:[{title:"直接打开原片，保留每个高光",body:"直接打开相册、外置硬盘或 NAS 里的长视频。标出任意多个片段、截图或 Live Photo，只导出真正值得保存的部分。",points:["支持本地存储、外置硬盘以及 SMB/WebDAV","一条视频标记多段，一次批量导出","不复制原片，不额外占用一整份视频空间",],shot:"source-file-clips",},{title:"正确处理元数据",body:"每一个片段或 Live Photo，都能匹配实际的时间和地点，相册不再杂乱无章",points:["智能计算片段的实际时间","保留 GPS 与拍摄设备信息","让相册时间线保持严格顺序",],shot:"photos-metadata-export",},{title:"路上先标，回家细看",body:"编辑记录通过 iCloud 自动同步。iPhone 上标注片段，回到 Mac 继续导出；自己的多台设备都能接着处理 NAS 上的同一份原片。",points:["只同步编辑记录，不同步视频文件","同一原片换了位置，也能自动对上","原生 tvOS app，或使用 AirPlay 投屏，大家一起看",],shot:"cross-device-editing",},{title:"智能寻找片段",body:"使用 Apple 设备提供的本地智能功能，先在长视频里找到候选时刻，再由你决定哪些片段值得导出。分析结果留在设备上。",points:["将语音转为文字，在支持的系统版本上翻译并导出字幕","识别声音特征，定位每一处欢笑","从一帧画面里识别主体，找到TA在视频里每一次出现",],shot:"local-intelligence",},{title:"每台设备都好用",body:"不是把同一个界面放大缩小。Trimly 针对 iPhone、iPad 和 Mac 分别优化。",points:["iPhone：小屏幕界面专门优化","iPad：触屏、键盘与自由窗口都支持","Mac：大屏幕和真实文件系统，高效操作","Apple TV：与亲朋好友一同标注片段",],shot:"device-workspaces",},{title:"HDR 与 Log",body:"媒体处理管线为 HDR、常见 Log 工作流和无损音频做好准备，让短片段保留真正重要的画质与声音。",points:["整个媒体处理管线为 HDR 设计",{text:"内置常见品牌热门设备的 LOG 还原 LUT",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"LUT 使用说明",},},"支持无损音频格式，甚至包括 PCM 原始数据",],shot:"pro-media-pipeline",},],privacy:{heading:"本地且私密",body:"无需 Trimly 账号，不追踪，不收集遥测数据。iCloud 只用于同步你的编辑记录与 LUT。",},footer:{home:"首页",support:"支持",privacy:"隐私政策",disclaimer:"Apple、Apple Log、iPhone、iPad、Mac 是 Apple Inc. 的商标。GoPro 是 GoPro, Inc. 的商标。大疆（DJI）是深圳市大疆创新科技有限公司的商标。影石（Insta360）是影石创新科技股份有限公司的商标。Trimly 为独立开发的应用，与上述公司及其关联企业无任何隶属、赞助或授权关系。内置 LUT 文件旨在帮助用户处理个人素材，仅供个人非商业用途。所有商标均归其各自所有者所有。",},legal:{eyebrow:"法律",title:"隐私政策",updated:"最后更新：2026 年 7 月 10 日",intro:"Trimly 在设备本地处理媒体。你的素材始终留在 iPhone、iPad 或 Mac 上。剪辑记录和 LUT 可以通过 iCloud 在你的 Apple 设备之间同步，但视频文件不会上传。本政策用直白的话说明这些设计对隐私意味着什么。",contactLabel:"对隐私有疑问？请联系",sections:[{h:"不收集数据",p:"Trimly 不收集、不存储、也不传输个人信息。没有数据分析，没有追踪，没有广告标识符，也没有任何形式的使用统计。",},{h:"iCloud 同步",p:"Trimly 不连接 Trimly 服务器，也不连接第三方服务。唯一的网络活动是 iCloud 同步：启用后，Apple 的 iCloud 会在你的设备之间同步剪辑记录和 LUT，相关数据受 Apple iCloud 条款与隐私政策约束。视频和音频文件不会上传，也不会通过 iCloud 同步。",},{h:"文件与照片访问",p:"当你从「文件」App、外接存储或照片图库打开媒体时，Trimly 只会读取你选择的内容，用来裁剪和导出。所有处理都在本机完成，导出的片段会保存到你选择的位置。Trimly 只在获得授权后访问照片图库，并且只用于导入或保存你选择的媒体。",},{h:"无账号，无第三方网络访问",p:"Trimly 没有账号系统，也不需要登录。除 Apple 内置的 iCloud 同步外，不使用任何分析服务或云端处理。",},{h:"AI 功能",p:"Trimly 中包含的 AI 功能均由 Apple 系统自带的框架实现。Trimly 没有携带，也不会下载任何第三方 AI 模型，更不会将用户数据提供给任何第三方 AI 服务商。所有的计算过程均在用户本地处理，并完全遵循 Apple 系统中 AI 功能的隐私政策。",},{h:"儿童隐私",p:"由于 Trimly 不收集数据，因此不会有意收集包括儿童在内的任何人的信息。",},{h:"政策变更",p:"如本政策有所变更，更新后的版本将连同新的日期发布在本页面。",},],},},ja:{indexTitle:"Trimly | 長い動画から、ハイライトを",privacyTitle:"Trimly | プライバシーポリシー",nav:{features:"機能",download:"ダウンロード",},hero:{heading:"長い動画はディスクに。\nハイライトは写真へ。",subtitle:"写真、外付けドライブ、NAS から元ファイルを直接開き、動画クリップ、静止画、Live Photo を好きな数だけマーク。実際の時刻、場所、画質を保ったまま写真アプリへ保存します。",cta:"App Storeでダウンロード",purchaseNote:"買い切りで iPhone、iPad、Mac、Apple TV 対応。サブスク不要。",},useCasesHeading:"長い録画の中にある、残したい瞬間へ。",useCases:[{title:"旅の一日",body:"到着、街並み、夕焼け、夕食をそれぞれのクリップに。時刻、場所、カメラ情報もそのまま残ります。",},{title:"ライブ",body:"まずは通しで録画。あとから最高のサビやステージの瞬間だけを保存できます。",},{title:"パーティー",body:"ろうそく、プレゼント、目を閉じて願う瞬間。その場面だけ切り出して共有し、みんなで残せます。",},{title:"アウトドア",body:"スキー、サーフィン、登山、サイクリング。自慢のターンやスプリントをマークして、最高の瞬間を見せられます。",},{title:"家族とペット",body:"家族やペットの小さな瞬間をクリップや Live Photo に。長い録画を探し直さず、思い出した時にすぐ見返せます。",},],proofSections:[{title:"元ファイルを開いて、\nハイライトだけ残す。",body:"別の機器で長く撮った動画も、スマートフォンへコピーする必要はありません。カードリーダーを挿せばよく、NAS 上のファイルも直接読み込めます。元ファイルが大きすぎる時は、必要に応じて書き出しサイズと画質を選べます。",points:["ローカル、外付け、SMB/WebDAV のファイル","書き出し品質を元品質から高圧縮まで選択","元ファイルをコピーせず、原本サイズの重複も不要",],shot:"source-file-clips",},{title:"メタデータを\n正しく扱う。",body:"クリップや Live Photo を、その瞬間の実際の時刻と場所に合わせて保存。写真ライブラリが散らかりません。",points:["クリップの実際の時刻を自動計算","GPS と撮影機材の情報を保持","時系列どおりに並ぶ写真ライブラリへ",],shot:"photos-metadata-export",},{title:"外でマーク、\n家で仕上げ。",body:"編集メモは iCloud 経由で同期。iPhone で付けた印を Mac でそのまま使えます。自分の複数のデバイスで NAS 上の同じファイルを続けて扱えます。",points:["同期するのは編集メモだけ、動画本体は除外","元ファイルの場所が変わっても編集メモを認識","tvOS アプリ、または AirPlay で一緒に視聴",],shot:"cross-device-editing",},{title:"見つけたい場面を賢く検索。",body:"Apple システムが提供するオンデバイス AI 機能を使い、長い動画の中から追加したい場面をすばやく見つけます。",points:["音声を文字起こし、翻訳にも対応","音の特徴を認識し、笑い声の位置を特定","1 フレームから被写体を認識し、登場箇所を検索",],shot:"local-intelligence",},{title:"画面ごとに、\n最適な操作感。",body:"同じ画面を拡大縮小しているだけではありません。iPhone、iPad、Mac それぞれに合う作りです。",points:["iPhone：小さな画面向けに最適化","iPad：タッチ、キーボード、サイズ自在のウインドウ","Mac：大画面と本物のファイルシステムで効率よく作業","Apple TV：家族や友人と一緒に視聴",],shot:"device-workspaces",shotAlt:"複数デバイスでの Trimly 編集画面",},{title:"プロ形式にも対応。",body:"短いクリップでも最高の品質を保てるよう、プロのクリエイターのために設計しました。",points:["HDR 前提のメディア処理",{text:"人気機種向けの LOG 復元 LUT を内蔵",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"LUT に関する注記",},},"PCM 生データを含むロスレス音声形式に対応",],shot:"pro-media-pipeline",shotAlt:"Trimly の音声波形と書き出しコントロール",},],privacy:{heading:"ローカルで、プライベート",body:"Trimly のアカウント、追跡、テレメトリはありません。iCloud は編集データと LUT の同期にのみ使います。",},footer:{home:"ホーム",support:"サポート",privacy:"プライバシーポリシー",disclaimer:"Apple、Apple Log、iPhone、iPad、MacはApple Inc.の商標です。GoProはGoPro, Inc.の商標です。DJIはSZ DJI Technology Co., Ltd.の商標です。Insta360はArashi Vision Inc.の商標です。Trimlyは独立して開発されたアプリであり、これらの企業とは提携・後援・承認の関係にありません。内蔵LUTはユーザー自身の映像を個人的・非商用目的で処理するために提供されています。すべての商標は各所有者に帰属します。",},legal:{eyebrow:"法的事項",title:"プライバシーポリシー",updated:"最終更新：2026年7月10日",intro:"Trimlyはメディアを端末内で処理します。映像はiPhone、iPad、Macに留まります。iCloudで同期されるのは編集データとLUTのみで、動画ファイルはアップロードされません。本ポリシーでは、それがあなたのプライバシーにとって何を意味するかを平易に説明します。",contactLabel:"プライバシーに関するご質問は",sections:[{h:"データを収集しません",p:"Trimlyは個人情報を収集・保存・送信しません。分析、トラッキング、広告識別子、利用テレメトリの類は一切ありません。",},{h:"iCloud同期",p:"TrimlyはTrimlyのサーバーや第三者サービスに接続しません。ネットワーク通信はiCloud同期のみです。有効にすると、AppleのiCloud経由で編集データとLUTをデバイス間に同期します。動画・音声ファイルはアップロードも同期もされません。同期データはAppleのiCloud利用規約とプライバシーポリシーの対象となります。",},{h:"ファイルと写真へのアクセス",p:"ファイルApp、外付けドライブ、写真ライブラリからメディアを開くと、Trimlyはトリミングと書き出しのためにそれを読み取るだけです。処理はすべてデバイス内でローカルに行われ、書き出したクリップはあなたが選んだ場所に保存されます。Trimlyはあなたの許可がある場合にのみ写真ライブラリにアクセスし、選択したメディアの読み込みや保存にのみ使用します。",},{h:"アカウントなし、第三者ネットワークアクセスなし",p:"Trimlyにはアカウント制度もサインインもありません。Apple組み込みのiCloud同期を除き、分析サービスやクラウド処理は一切使用しません。",},{h:"AI機能",p:"Trimlyに含まれるAI機能は、すべてAppleのシステムに標準搭載されたフレームワークによって実装されています。Trimlyがサードパーティ製のAIモデルを同梱したり、ダウンロードしたりすることはありません。また、ユーザーデータを第三者のAIサービス事業者に提供することもありません。すべての処理はユーザーのデバイス上でローカルに実行され、AppleのシステムにおけるAI機能のプライバシーポリシーに完全に準拠します。",},{h:"子どものプライバシー",p:"Trimlyはデータを一切収集しないため、子どもを含むいかなる人物の情報も意図的に収集することはありません。",},{h:"ポリシーの変更",p:"本ポリシーを変更する場合は、更新版を新しい日付とともにこのページに掲載します。",},],},},ko:{indexTitle:"Trimly | 긴 영상에서 하이라이트로",privacyTitle:"Trimly | 개인정보 처리방침",nav:{features:"기능",download:"다운로드",},hero:{heading:"긴 영상은 디스크에.\n하이라이트는 사진 앱으로.",subtitle:"사진 앱, 외장 드라이브, NAS에서 원본을 바로 여세요. 원하는 만큼 영상 클립, 스틸 이미지, Live Photo를 표시하고 실제 시간과 장소를 보존해 사진 앱에 저장하세요.",cta:"App Store에서 다운로드",purchaseNote:"한 번 구매로 iPhone, iPad, Mac, Apple TV 모두. 구독은 필요 없습니다.",},useCasesHeading:"긴 기록 속에 숨어 있는 순간들.",useCases:[{title:"여행의 하루",body:"도착, 거리 풍경, 노을, 저녁을 각각의 클립으로. 시간, 장소, 카메라 정보까지 그대로 남습니다.",},{title:"공연",body:"일단 전체를 녹화하세요. 가장 멋진 후렴과 무대 순간만 따로 저장할 수 있습니다.",},{title:"파티",body:"촛불, 선물, 눈을 감고 소원을 비는 순간. 그 장면만 잘라 공유하고 모두가 간직할 수 있습니다.",},{title:"아웃도어",body:"스키, 서핑, 등산, 사이클링. 가장 뿌듯한 턴과 스프린트를 표시해 최고의 순간을 보여주세요.",},{title:"가족과 반려동물",body:"아이의 첫걸음이나 반려동물의 재미있는 반응처럼, 긴 영상을 다시 찾지 않아도 간직하고 싶은 순간을 남기세요.",},],proofSections:[{title:"원본을 열고,\n하이라이트만 남기기.",body:"다른 기기로 길게 찍은 영상도 휴대폰에 복사할 필요가 없습니다. 카드 리더를 꽂기만 하면 되고, NAS의 파일도 바로 읽을 수 있습니다. 원본 파일이 너무 크다면 필요한 내보내기 크기와 화질을 선택할 수 있습니다.",points:["로컬 저장소, 외장 드라이브, SMB/WebDAV 지원","내보낼 때 원본부터 고압축까지 품질 선택","원본을 복사하지 않고 전체 크기의 중복도 만들지 않음",],shot:"source-file-clips",},{title:"메타데이터를 올바르게 처리.",body:"각 클립과 Live Photo가 실제 시간과 장소에 맞게 남아, 사진 보관함이 더 이상 어수선해지지 않습니다.",points:["클립의 실제 시각 자동 계산","GPS와 촬영 기기 정보 보존","시간순으로 깔끔하게 정렬되는 사진 보관함",],shot:"photos-metadata-export",},{title:"밖에서 표시하고, 집에서 마무리.",body:"편집 기록이 iCloud를 통해 동기화됩니다. iPhone에서 표시한 구간을 Mac에서 이어서 내보내고, 여러 개인 기기에서 NAS의 같은 원본을 계속 작업할 수 있습니다.",points:["편집 기록만 동기화, 영상 파일은 제외","원본 위치가 바뀌어도 편집 기록을 인식","네이티브 tvOS 앱, 또는 AirPlay로 함께 시청",],shot:"cross-device-editing",},{title:"클립을 똑똑하게 찾기.",body:"Apple 시스템이 제공하는 기기 내 AI 기능으로 긴 영상 속에서 추가하고 싶은 장면을 빠르게 찾습니다.",points:["음성을 텍스트로 변환하고 번역도 지원","소리 특징을 인식해 모든 웃음 지점 찾기","한 프레임에서 피사체를 인식해 영상 속 등장 장면 모두 찾기",],shot:"local-intelligence",},{title:"각 화면에 맞는 사용감.",body:"같은 화면을 키우고 줄인 앱이 아닙니다. iPhone, iPad, Mac에 맞게 각각 다듬었습니다.",points:["iPhone: 작은 화면에 맞춘 레이아웃","iPad: 터치, 키보드, 자유로운 창 크기","Mac: 큰 화면과 실제 파일 시스템에서 효율적인 작업","Apple TV: 가족, 친구와 함께 시청",],shot:"device-workspaces",shotAlt:"여러 기기에서 보이는 Trimly 편집 화면",},{title:"전문 포맷도 지원.",body:"짧은 클립도 최상의 품질을 유지할 수 있도록 전문 크리에이터를 위해 설계했습니다.",points:["HDR을 고려한 미디어 처리",{text:"인기 기기용 LOG 복원 LUT 내장",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"LUT 안내",},},"PCM 원시 데이터를 포함한 무손실 오디오 형식 지원",],shot:"pro-media-pipeline",shotAlt:"Trimly 오디오 파형과 내보내기 컨트롤",},],privacy:{heading:"로컬에서, 비공개로",body:"Trimly 계정, 추적, 텔레메트리가 없습니다. iCloud는 편집 기록과 LUT 동기화에만 사용됩니다.",},footer:{home:"홈",support:"지원",privacy:"개인정보 처리방침",disclaimer:"Apple, Apple Log, iPhone, iPad, Mac은 Apple Inc.의 상표입니다. GoPro는 GoPro, Inc.의 상표입니다. DJI는 SZ DJI Technology Co., Ltd.의 상표입니다. Insta360은 Arashi Vision Inc.의 상표입니다. Trimly는 독립적으로 개발된 앱이며 위 회사들과 제휴·후원·승인 관계가 없습니다. 포함된 LUT 파일은 사용자가 자신의 촬영본을 개인적·비상업적 용도로 처리하도록 제공됩니다. 모든 상표는 각 소유자에게 귀속됩니다.",},legal:{eyebrow:"법적 고지",title:"개인정보 처리방침",updated:"최종 업데이트: 2026년 7월 10일",intro:"Trimly는 미디어를 기기에서 로컬로 처리합니다. 촬영본은 iPhone, iPad, Mac에 그대로 둡니다. iCloud로는 편집 기록과 LUT만 동기화되며, 동영상 파일은 업로드되지 않습니다. 이 방침은 그것이 프라이버시에 무엇을 의미하는지 쉬운 말로 설명합니다.",contactLabel:"프라이버시 문의는",sections:[{h:"데이터 수집 없음",p:"Trimly는 개인정보를 수집·저장·전송하지 않습니다. 분석, 추적, 광고 식별자, 이용 텔레메트리가 전혀 없습니다.",},{h:"iCloud 동기화",p:"Trimly는 Trimly 서버나 제3자 서비스에 연결하지 않습니다. 유일한 네트워크 활동은 iCloud 동기화입니다. 활성화하면 Apple iCloud를 통해 편집 기록과 LUT를 기기 간에 동기화합니다. 동영상·오디오 파일은 업로드되거나 동기화되지 않습니다. 동기화 데이터는 Apple iCloud 약관 및 개인정보 처리방침의 적용을 받습니다.",},{h:"파일 및 사진 접근",p:"파일 앱, 외장 드라이브, 사진 보관함에서 미디어를 열면 Trimly는 자르고 내보내기 위해 읽을 뿐입니다. 모든 처리는 기기에서 로컬로 이루어지며, 내보낸 클립은 선택한 위치에 저장됩니다. Trimly는 허용된 경우에만 사진 보관함에 접근하며, 선택한 미디어를 가져오거나 저장하는 데만 사용합니다.",},{h:"계정 없음, 제3자 네트워크 접근 없음",p:"Trimly에는 계정 시스템이나 로그인이 없습니다. Apple 내장 iCloud 동기화 외에는 어떤 분석 서비스나 클라우드 처리도 사용하지 않습니다.",},{h:"AI 기능",p:"Trimly에 포함된 AI 기능은 모두 Apple 시스템에 기본 제공되는 프레임워크로 구현됩니다. Trimly는 어떤 제3자 AI 모델도 포함하지 않으며, 앞으로도 다운로드하지 않습니다. 또한 사용자 데이터를 어떤 제3자 AI 서비스 제공업체에도 제공하지 않습니다. 모든 처리는 사용자의 기기에서 로컬로 이루어지며, Apple 시스템의 AI 기능에 적용되는 개인정보 처리방침을 전적으로 따릅니다.",},{h:"아동 프라이버시",p:"Trimly는 데이터를 전혀 수집하지 않으므로 아동을 포함해 누구의 정보도 의도적으로 수집하지 않습니다.",},{h:"방침 변경",p:"이 방침이 변경되면 업데이트된 버전이 새 날짜와 함께 이 페이지에 게시됩니다.",},],},},es:{indexTitle:"Trimly | Del vídeo largo al momento importante",privacyTitle:"Trimly | Política de privacidad",nav:{features:"Funciones",download:"Descargar",},hero:{heading:"Vídeos largos en el disco.\nMomentos importantes en Fotos.",subtitle:"Abre el original desde Fotos, un disco externo o tu NAS. Marca tantos clips, imágenes fijas o Live Photos como quieras y guárdalos en Fotos con su hora y lugar reales.",cta:"Descargar en el App Store",purchaseNote:"Una compra para iPhone, iPad, Mac y Apple TV. Sin suscripción.",},useCasesHeading:"Para esos momentos escondidos en vídeos largos.",useCases:[{title:"Días de viaje",body:"Llegada, calles, atardecer, cena. Convierte el día en clips y conserva hora, lugar y datos de cámara.",},{title:"Conciertos",body:"Graba el set completo. Guarda aparte los mejores estribillos y momentos del escenario.",},{title:"Fiestas",body:"Velas, regalos, ojos cerrados al pedir un deseo. Recorta ese momento, compártelo con el grupo y deja que todos lo guarden.",},{title:"Aire libre",body:"Esquí, surf, montaña, ciclismo. Marca ese giro o sprint del que estás orgulloso y enseña tu mejor momento.",},{title:"Familia y mascotas",body:"Guarda los primeros pasos, una reacción divertida de tu mascota o cualquier pequeño momento sin volver a buscarlo en todo el vídeo.",},],proofSections:[{title:"Abre el original.\nQuédate con cada momento.",body:"¿Grabaste un vídeo largo en otro dispositivo? No hace falta copiarlo al teléfono: conecta un lector de tarjetas o lee archivos directamente desde tu NAS. Si el original pesa demasiado, elige el tamaño y la calidad de exportación que necesites.",points:["Compatible con almacenamiento local, discos externos y SMB/WebDAV","Calidad al exportar: original o comprimida","Sin copiar el original ni crear un duplicado de tamaño completo",],shot:"source-file-clips",},{title:"Metadatos tratados como corresponde.",body:"Cada clip o Live Photo puede alinearse con la hora y el lugar reales del momento, para que tu biblioteca deje de estar desordenada.",points:["Calcula la hora real de cada clip","Conserva GPS y datos de la cámara","Devuelve a tu biblioteca una línea de tiempo ordenada",],shot:"photos-metadata-export",},{title:"Marca fuera. Termina en casa.",body:"Tus notas de edición se sincronizan mediante iCloud. Marca en el iPhone y continúa en el Mac cuando quieras; tus propios dispositivos pueden seguir trabajando con el mismo original en tu NAS.",points:["Sincroniza notas, no vídeos grandes","Mueve el original; las ediciones siguen enlazadas","App nativa para tvOS, o AirPlay para ver juntos",],shot:"cross-device-editing",},{title:"Encuentra clips con inteligencia.",body:"Usa las funciones de IA local que ofrece el sistema de Apple para encontrar rápidamente los momentos que quieres añadir dentro de vídeos largos.",points:["Transcribe la voz a texto, con traducción incluida","Reconoce patrones de sonido para ubicar cada risa","Identifica un sujeto en un fotograma y encuentra cada vez que aparece en el vídeo",],shot:"local-intelligence",},{title:"Hecho para cada pantalla.",body:"No es una interfaz estirada de un dispositivo a otro. iPhone, iPad y Mac tienen su propio ritmo.",points:["iPhone: interfaz cuidada para pantallas pequeñas","iPad: toque, teclado y ventanas ajustables","Mac: pantalla grande y sistema de archivos real","Apple TV: para ver juntos con familia y amigos",],shot:"device-workspaces",shotAlt:"Interfaz de edición de Trimly en distintos dispositivos",},{title:"Formatos profesionales compatibles.",body:"Pensado para creadores profesionales, para que incluso los clips cortos conserven la mejor calidad.",points:["Procesamiento preparado para HDR",{text:"LUTs de recuperación LOG para dispositivos populares",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"Nota sobre LUTs",},},"Audio sin pérdida, incluso PCM sin procesar",],shot:"pro-media-pipeline",shotAlt:"Forma de onda de audio y controles de exportación de Trimly",},],privacy:{heading:"Local y privado",body:"Sin cuenta de Trimly, seguimiento ni telemetría. iCloud solo sincroniza tus notas de edición y LUTs.",},footer:{home:"Inicio",support:"Soporte",privacy:"Política de privacidad",disclaimer:"Apple, Apple Log, iPhone, iPad y Mac son marcas comerciales de Apple Inc. GoPro es una marca comercial de GoPro, Inc. DJI es una marca comercial de SZ DJI Technology Co., Ltd. Insta360 es una marca comercial de Arashi Vision Inc. Trimly se desarrolla de forma independiente y no está afiliada, patrocinada ni respaldada por ninguna de estas empresas. Los archivos LUT incluidos ayudan a los usuarios a procesar su propio metraje solo para uso personal y no comercial. Todas las marcas pertenecen a sus respectivos propietarios.",},legal:{eyebrow:"Legal",title:"Política de privacidad",updated:"Última actualización: 10 de julio de 2026",intro:"Trimly procesa tu metraje en el dispositivo. Tus archivos permanecen en tu iPhone, iPad o Mac. Los registros de edición y LUTs pueden sincronizarse entre tus dispositivos Apple mediante iCloud; los archivos de vídeo nunca se suben. Esta política explica, en términos sencillos, qué significa eso para tu privacidad.",contactLabel:"¿Preguntas sobre privacidad? Escríbenos a",sections:[{h:"Sin recopilación de datos",p:"Trimly no recopila, almacena ni transmite información personal. No hay analíticas, seguimiento, identificadores publicitarios ni telemetría de ningún tipo.",},{h:"Sincronización iCloud",p:"Trimly no se conecta a servidores de Trimly ni a servicios de terceros. La única actividad de red es la sincronización iCloud, que usa el iCloud de Apple para mantener tus registros de edición y LUTs sincronizados entre tus dispositivos cuando la activas. Los archivos de vídeo y audio nunca se suben ni se sincronizan; los datos sincronizados están sujetos a los términos y la política de privacidad de iCloud de Apple.",},{h:"Acceso a Archivos y Fotos",p:"Cuando abres medios desde la app Archivos, un disco externo o tu biblioteca de Fotos, Trimly solo los lee para que puedas recortarlos y exportarlos. Todo el procesamiento ocurre localmente en tu dispositivo y los clips exportados se guardan donde elijas. Trimly accede a tu biblioteca de Fotos solo con tu permiso y únicamente para importar o guardar los medios que selecciones.",},{h:"Sin cuenta ni acceso de red de terceros",p:"Trimly no tiene sistema de cuentas ni inicio de sesión. Aparte de la sincronización iCloud integrada de Apple, no utiliza ningún servicio de analíticas ni procesamiento en la nube.",},{h:"Funciones de IA",p:"Todas las funciones de IA incluidas en Trimly están implementadas con frameworks integrados en los sistemas de Apple. Trimly no incorpora ni descargará nunca modelos de IA de terceros. Tampoco comparte datos de los usuarios con proveedores externos de servicios de IA. Todo el procesamiento se realiza localmente en el dispositivo del usuario y se ajusta por completo a las políticas de privacidad aplicables a las funciones de IA de los sistemas de Apple.",},{h:"Privacidad de menores",p:"Como Trimly no recopila datos, no recopila a sabiendas información de nadie, incluidos los menores.",},{h:"Cambios en esta política",p:"Si esta política cambia, la versión actualizada se publicará en esta página con una nueva fecha.",},],},},ar:{indexTitle:"Trimly | من الفيديو الطويل إلى اللحظة المهمة",privacyTitle:"Trimly | سياسة الخصوصية",nav:{features:"المميزات",download:"حمِّل",},hero:{heading:"الفيديوهات الطويلة على القرص.\nواللحظات المهمة في الصور.",subtitle:"افتح الأصل مباشرة من الصور أو قرص خارجي أو NAS. علّم أي عدد تريده من المقاطع والصور وLive Photos واحفظها في الصور مع وقتها ومكانها الحقيقيين.",cta:"حمِّل من App Store",purchaseNote:"شراء واحد لـ iPhone وiPad وMac وApple TV. بلا اشتراك.",},useCasesHeading:"للحظات المختبئة داخل التسجيلات الطويلة.",useCases:[{title:"أيام السفر",body:"الوصول، الشوارع، الغروب، العشاء. حوّل اليوم إلى مقاطع مع حفظ الوقت والمكان وتفاصيل الكاميرا.",},{title:"العروض",body:"سجّل العرض كاملاً، ثم احفظ أفضل المقاطع ولحظات المسرح على حدة.",},{title:"التجمعات",body:"الشموع، الهدايا، لحظة إغماض العينين لتمني أمنية. اقتطعها وشاركها مع المجموعة ليحتفظ بها الجميع.",},{title:"المغامرات",body:"تزلج، أمواج، جبال، دراجات. علّم المنعطف أو الانطلاقة التي تفتخر بها واعرض أفضل لحظاتك.",},{title:"العائلة والحيوانات الأليفة",body:"احتفظ بالخطوات الأولى أو بردّة فعل طريفة لحيوانك الأليف أو بأي لحظة صغيرة تريد العودة إليها، من دون البحث في التسجيل كله.",},],proofSections:[{title:"افتح الأصل.\nواحتفظ بكل لحظة مهمة.",body:"افتح التسجيلات الطويلة مباشرة من الصور أو قرص خارجي أو NAS. علّم أي عدد تريده من المقاطع والصور وLive Photos، ثم صدّر ما يستحق الاحتفاظ به فقط.",points:["دعم التخزين المحلي والأقراص الخارجية وSMB/WebDAV","جودة التصدير: من الأصلية إلى الضغط العالي","من دون نسخ الأصل أو إنشاء نسخة كاملة الحجم",],shot:"source-file-clips",},{title:"معالجة صحيحة للبيانات الوصفية.",body:"يمكن لكل مقطع أو Live Photo أن يطابق وقت اللحظة ومكانها الحقيقيين، حتى لا تصبح مكتبة الصور فوضوية.",points:["حساب الوقت الحقيقي لكل مقطع","الحفاظ على GPS وتفاصيل الكاميرا","إعادة ترتيب مكتبة الصور على خط زمني دقيق",],shot:"photos-metadata-export",},{title:"علّم خارجاً. وأنهِ في البيت.",body:"تتزامن ملاحظات التحرير عبر iCloud. علّم المقاطع على iPhone، ثم تابع على Mac عندما تكون جاهزاً؛ ويمكن لأجهزتك الشخصية متابعة العمل على الأصل نفسه في NAS.",points:["تزامن ملاحظات التحرير فقط، لا الفيديو","حتى بعد نقل الأصل، تبقى التعديلات مرتبطة","تطبيق tvOS أصلي، أو AirPlay للمشاهدة معاً",],shot:"cross-device-editing",},{title:"اعثر على المقاطع بذكاء.",body:"استخدم ميزات الذكاء الاصطناعي المحلية التي يوفرها نظام Apple للعثور سريعاً على اللقطات التي تريد إضافتها داخل الفيديوهات الطويلة.",points:["تحويل الكلام إلى نص، مع دعم الترجمة","التعرّف على خصائص الصوت لتحديد كل ضحكة","التعرّف على الشخص من إطار واحد والعثور على كل ظهور له في الفيديو",],shot:"local-intelligence",},{title:"مصمم لكل شاشة.",body:"ليست واجهة واحدة ممدودة على كل الأجهزة. لكل من iPhone وiPad وMac إيقاعه المناسب.",points:["iPhone: واجهة مضبوطة للشاشات الصغيرة","iPad: لمس ولوحة مفاتيح ونوافذ حرة","Mac: شاشة كبيرة ونظام ملفات حقيقي","Apple TV: للمشاهدة مع العائلة والأصدقاء",],shot:"device-workspaces",shotAlt:"واجهة تحرير Trimly على أجهزة مختلفة",},{title:"دعم للصيغ الاحترافية.",body:"مصمم للمبدعين المحترفين حتى تحتفظ المقاطع القصيرة أيضاً بأفضل جودة.",points:["معالجة وسائط جاهزة لـ HDR",{text:"LUT استعادة LOG مدمجة للأجهزة الشائعة",note:{label:"*",href:"#lut-disclaimer",ariaLabel:"ملاحظة حول LUT",},},"دعم الصوت بلا فقدان، بما في ذلك PCM الخام",],shot:"pro-media-pipeline",shotAlt:"موجة الصوت وعناصر التحكم في التصدير داخل Trimly",},],privacy:{heading:"محلي وخاص",body:"لا حساب لـ Trimly ولا تتبع أو قياس عن بُعد. يُستخدم iCloud فقط لمزامنة تعديلاتك وملفات LUT.",},footer:{home:"الرئيسية",support:"الدعم",privacy:"سياسة الخصوصية",disclaimer:"Apple وApple Log وiPhone وiPad وMac علامات تجارية لـ Apple Inc. GoPro علامة تجارية لـ GoPro, Inc. DJI علامة تجارية لـ SZ DJI Technology Co., Ltd. Insta360 علامة تجارية لـ Arashi Vision Inc. Trimly تطبيق مستقل ولا يرتبط بأي من هذه الشركات ولا يرعاه ولا يحظى باعتمادها. ملفات LUT المدمجة مخصّصة لمساعدة المستخدمين على معالجة لقطاتهم الشخصية لأغراض شخصية وغير تجارية فقط. جميع العلامات التجارية ملك لأصحابها.",},legal:{eyebrow:"قانوني",title:"سياسة الخصوصية",updated:"آخر تحديث: 10 يوليو 2026",intro:"Trimly يعالج وسائطك على جهازك. تبقى لقطاتك على iPhone أو iPad أو Mac. يمكن مزامنة سجلات التحرير وملفات LUT عبر iCloud بين أجهزة Apple؛ ملفات الفيديو لا تُرفَع أبداً. تشرح هذه السياسة، بلغة بسيطة، ما يعنيه ذلك لخصوصيتك.",contactLabel:"لأي استفسار حول الخصوصية، تواصل معنا على",sections:[{h:"لا جمع للبيانات",p:"لا تجمع Trimly أي معلومات شخصية ولا تخزّنها ولا تنقلها. لا تحليلات، لا تتبع، لا معرّفات إعلانية، ولا أي قياس للاستخدام من أي نوع.",},{h:"مزامنة iCloud",p:"لا تتصل Trimly بخوادم Trimly أو أي خدمات لأطراف ثالثة. النشاط الشبكي الوحيد هو مزامنة iCloud، التي تستخدم iCloud من Apple لمزامنة سجلات التحرير وملفات LUT بين أجهزتك عند تفعيلها. ملفات الفيديو والصوت لا تُرفَع ولا تُزامَن، وتخضع البيانات المُزامَنة لشروط iCloud وسياسة خصوصية Apple.",},{h:"الوصول إلى الملفات والصور",p:"عندما تفتح وسائط من تطبيق الملفات أو قرص خارجي أو مكتبة الصور، تقرأها Trimly فقط لتتمكن من القص والتصدير. تتم جميع المعالجات محلياً على جهازك، وتُحفَظ المقاطع المصدَّرة في المكان الذي تختاره. لا تصل Trimly إلى مكتبة الصور إلا بإذنك، ولاستيراد أو حفظ الوسائط التي تحددها فقط.",},{h:"لا حسابات ولا وصول شبكي لأطراف ثالثة",p:"لا يوجد في Trimly نظام حسابات أو تسجيل دخول. باستثناء مزامنة iCloud المدمجة من Apple، لا يستخدم أي خدمات تحليلات أو معالجة سحابية.",},{h:"ميزات الذكاء الاصطناعي",p:"جميع ميزات الذكاء الاصطناعي في Trimly مُنفّذة باستخدام أطر العمل المدمجة في أنظمة Apple. لا يتضمن Trimly أي نماذج ذكاء اصطناعي تابعة لجهات خارجية، ولن يقوم بتنزيلها مطلقاً. كما أنه لا يزوّد أي مزود خارجي لخدمات الذكاء الاصطناعي ببيانات المستخدمين. تتم كل عمليات المعالجة محلياً على جهاز المستخدم، وبما يتوافق بالكامل مع سياسات الخصوصية الخاصة بميزات الذكاء الاصطناعي في أنظمة Apple.",},{h:"خصوصية الأطفال",p:"بما أن Trimly لا تجمع أي بيانات على الإطلاق، فإنها لا تجمع عن قصد أي معلومات من أي شخص، بمن فيهم الأطفال.",},{h:"التعديلات على هذه السياسة",p:"إذا تغيّرت هذه السياسة، سيُنشر الإصدار المحدَّث على هذه الصفحة مع تاريخ جديد.",},],},},};
